    ["STR_ID_SkillEraser[15988][Text206]"] = "@STR_COMMON[107]",
    ["STR_ID_SkillEraser[15988][Text207]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text208]"] = "@STR_COMMON[108]",
    ["STR_ID_SkillEraser[15988][Text209]"] = "I'm sorry, you need at least 3 GhostHorn in order for me to help you.",
    ["STR_ID_SkillEraser[15988][Text210]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text211]"] = "@STR_COMMON[108]",
