    ["STR_ID_SkillEraser[15988][Text216]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text217]"] = "@STR_COMMON[110]",
    ["STR_ID_SkillEraser[15988][Text218]"] = "@STR_COMMON[111]",
    ["STR_ID_SkillEraser[15988][Text219]"] = "@STR_COMMON[103]",
    ["STR_ID_SkillEraser[15988][Text220]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text221]"] = "You successfully exchange the ImpureVigor for an 1DayVIP!",
    ["STR_ID_SkillEraser[15988][Text222]"] = "@STR_COMMON[105]",
    ["STR_ID_SkillEraser[15988][Text223]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text224]"] = "@STR_COMMON[106]",
    ["STR_ID_SkillEraser[15988][Text225]"] = "@STR_COMMON[107]",
    ["STR_ID_SkillEraser[15988][Text226]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text227]"] = "@STR_COMMON[108]",
    ["STR_ID_SkillEraser[15988][Text228]"] = "@STR_COMMON[109]",
    ["STR_ID_SkillEraser[15988][Text229]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text230]"] = "@STR_COMMON[110]",
    ["STR_ID_SkillEraser[15988][Text231]"] = "@STR_COMMON[111]",
    ["STR_ID_SkillEraser[15988][Text232]"] = "Hi, you have got the meterial i want. Do you come for the Bomb?",
    ["STR_ID_SkillEraser[15988][Text233]"] = "Five~pieces~of~Saltpeter~and~one~piece~of~Sulphur~are~required~to~make~the~Bomb.~And~I~charge~a~fee~of~30,000~silvers.",
    ["STR_ID_SkillEraser[15988][Text234]"] = "It`s used to blow down the guild gate! I participated in a guild war and witnessed lots of people lost their lives when attacking the gate.",
    ["STR_ID_SkillEraser[15988][Text235]"] = "No problem. But you know such bombs are powerful and dangerous. Whoever uses it to destroy a guild gate will be killed by the bomb, too!",
    ["STR_ID_SkillEraser[15988][Text236]"] = "Good. You`re going to collect 5 Saltpeter and a Sulphur. Besides, you`ll need to pay 30,000 Silver as fees.",
    ["STR_ID_SkillEraser[15988][Text237]"] = "You~can~get~Saltpeter~from~my~friend~OldQuarrier~in~Ape~City~and~get~Sulphur~from~the~Bandits~nearby.",
    ["STR_ID_SkillEraser[15988][Text238]"] = "You can take the Bomb away. Remember that you`ll be killed once you use it to destroy the guild gate!",
    ["STR_ID_SkillEraser[15988][Text239]"] = "Let me guess. It`s Norbert who asked you to come here. Am I right?",
    ["STR_ID_SkillEraser[15988][Text240]"] = "My~pleasure.~Here~you~are.",
    ["STR_ID_SkillEraser[15988][Text241]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text242]"] = "Are~you~coming~for~Saltpeter?~Since~Norbert~invented~Bomb,~I~have~been~kept~busy~with~supplying~Saltpeter~for~him.",
    ["STR_ID_SkillEraser[15988][Text243]"] = "It~is~powerful~and~used~to~bomb~out~City~Gate.~If~you`re~interested~in~it,~you~can~visit~Norbert~ for the details. He lives in~the~small~village~of~the~Maple Forest",
    ["STR_ID_SkillEraser[15988][Text244]"] = "@STR_COMMON[652]",
    ["STR_ID_SkillEraser[15988][Text245]"] = "@STR_COMMON[652]",
    ["STR_ID_SkillEraser[15988][Text246]"] = "You`re married. To change your gender, you need to get a divorce, first.",
    ["STR_ID_SkillEraser[15988][Text247]"] = "Please remove your garment.",
    ["STR_ID_SkillEraser[15988][Text248]"] = "Gender reassignment requires 1,075 CPs. Make sure you have enough money with you.",
    ["STR_ID_SkillEraser[15988][Text249]"] = "To make gender reassignment as simple as possible, I want you to be single, not married. Make sure you`ve",
    ["STR_ID_SkillEraser[15988][Text250]"] = "Good day! If you want to turn a new page in your life, you can pay me 810 CPs to get a new name. Your new name will be registered, immediately.",
    ["STR_ID_SkillEraser[15988][Text251]"] = "Do you want to reset your name for 10k Conquer Points ?",
    ["STR_ID_SkillEraser[15988][Text252]"] = "Your name reset was finished succesfully!",
    ["STR_ID_SkillEraser[15988][Text253]"] = "@STR_COMMON[15]",
    ["STR_ID_SkillEraser[15988][Text254]"] = "At your service! Oh, no... I`m sorry. You`d better check your bag, again. You don`t have enough CPs to rename yourself. It takes 810 CPs, and I`m not allowed to offer any discounts.",
    ["STR_ID_SkillEraser[15988][Text255]"] = "@STR_COMMON[181]",
    ["STR_ID_SkillEraser[15988][Text256]"] = "@STR_COMMON[182]",
    ["STR_ID_SkillEraser[15988][Text257]"] = "@STR_COMMON[181]",
    ["STR_ID_SkillEraser[15988][Text258]"] = "@STR_COMMON[182]",
    ["STR_ID_SkillEraser[15988][Text259]"] = "@STR_COMMON[181]",
    ["STR_ID_SkillEraser[15988][Text260]"] = "@STR_COMMON[182]",
    ["STR_ID_SkillEraser[15988][Text261]"] = "@STR_COMMON[181]",
    ["STR_ID_SkillEraser[15988][Text262]"] = "@STR_COMMON[182]",
    ["STR_ID_SkillEraser[15988][Text263]"] = "@STR_COMMON[181]",
    ["STR_ID_SkillEraser[15988][Text264]"] = "@STR_COMMON[182]",
    ["STR_ID_SkillEraser[15988][Text265]"] = "I come from the stone, and so I am the Stone Ape. The other apes regard me as a freak, but I`m not! Please, go and ask the Solar Saint what I am!",
    ["STR_ID_SkillEraser[15988][Text266]"] = "I was born from the rocks used to restore cracks in the sky? I can`t believe my ears! And what is this? A Divine Calix? Solar Saint told you that I can",
    ["STR_ID_SkillEraser[15988][Text267]"] = "Thank you! I feel much more powerful now! I will work hard to become a worthy immortal!",
    ["STR_ID_SkillEraser[15988][Text268]"] = "Where is the Divine Calix? I want to drink the water inside!",
    ["STR_ID_SkillEraser[15988][Text269]"] = "@STR_COMMON[442]",
    ["STR_ID_SkillEraser[15988][Text270]"] = "@STR_COMMON[442]",
    ["STR_ID_SkillEraser[15988][Text271]"] = "No problem! I will do everything I can to help Carpenter Jack fix the wooden bridge! Why not take a short break? Or better yet, I have something else for you to do!",
    ["STR_ID_SkillEraser[15988][Text272]"] = "Please don`t stand and in the way! The transport column will pass through here!",
    ["STR_ID_SkillEraser[15988][Text273]"] = "@STR_COMMON[444]",
    ["STR_ID_SkillEraser[15988][Text274]"] = "I can prepare the wood needed by the carpenter, but I`m worried about the Giant Apes. Slay 50 Giant Apes for me in the Love Canyon, in case they attack the wood transports.",
    ["STR_ID_SkillEraser[15988][Text275]"] = "The Sand Monsters L68 are too strong for me. Please go kill them and protect me!",
    ["STR_ID_SkillEraser[15988][Text276]"] = "Help, help! It`s so good to see you here. The Sand Monsters L68 blocked my way home. Please, I don`t want to die here. Could you kill them for me?",
    ["STR_ID_SkillEraser[15988][Text277]"] = "There are many dangerous creatures in the desert. Once you step through here, I won`t be able to protect you anymore. Take care.",
    ["STR_ID_SkillEraser[15988][Text278]"] = "The Sandbag is open! We did it!",
    ["STR_ID_SkillEraser[15988][Text279]"] = "You`re going to collect some water from the source in the city and spread the water over the city gates.",
    ["STR_ID_SkillEraser[15988][Text280]"] = "@STR_COMMON[26]",
    ["STR_ID_SkillEraser[15988][Text281]"] = "A lot of yellow sand? That`s weird. This information is important. Thanks for you help!",
    ["STR_ID_SkillEraser[15988][Text282]"] = "@STR_COMMON[465]",
    ["STR_ID_SkillEraser[15988][Text283]"] = "@STR_COMMON[465]",
    ["STR_ID_SkillEraser[15988][Text284]"] = "The Sand Monsters want to use the Sandbags to attack the city? Thanks for the information. Here`s your reward!",
    ["STR_ID_SkillEraser[15988][Text285]"] = "The Sand Monsters must have something to do with the weird yellow sand. I need you to turn to the Sand Monsters for some clues.",
    ["STR_ID_SkillEraser[15988][Text286]"] = "The Sand Monsters must have something to do with the weird yellow sand. I need you to return to the Sand Monsters to look for clues.",
    ["STR_ID_SkillEraser[15988][Text287]"] = "These Sandbags can`t be opened somehow. I`ve tried many ways, and even the a blade doesn`t work. Can you deliver it to Taoist Yu? Maybe he can figure that out.",
    ["STR_ID_SkillEraser[15988][Text288]"] = "These Sandbags can`t be opened, no matter what I do. I`ve tried many ways, and even a blade won`t work. Can you take it to Taoist Yu? Maybe he can figure it out.",
    ["STR_ID_SkillEraser[15988][Text289]"] = "Freez War is a skill based team event. Hitting the enemy team will lock ",
    ["STR_ID_SkillEraser[15988][Text290]"] = "@STR_COMMON[44]",
    ["STR_ID_SkillEraser[15988][Text291]"] = "@STR_COMMON[44]",
    ["STR_ID_SkillEraser[15988][Text292]"] = "@STR_COMMON[658]",
    ["STR_ID_SkillEraser[15988][Text293]"] = "@STR_COMMON[659]",
    ["STR_ID_SkillEraser[15988][Text294]"] = "Why you are here? Speak!",
    ["STR_ID_SkillEraser[15988][Text295]"] = "Good job! Take your reward!",
    ["STR_ID_SkillEraser[15988][Text296]"] = "Kill 50 Heresy Snakemen for me! They are my enemies!",
    ["STR_ID_SkillEraser[15988][Text297]"] = "The Heresy Snakemen are enemies to my race! I want you to kill 50 Heresy Snakemen for me!",
    ["STR_ID_SkillEraser[15988][Text298]"] = "Oh? A Catholicon? Give it to me!",
    ["STR_ID_SkillEraser[15988][Text299]"] = "No criminal can escape from my hands! Here`s a letter for the DC Vice Captain. I need you to head to the Desert and deliver this letter to him.",
    ["STR_ID_SkillEraser[15988][Text300]"] = "Thank you for all you have done. Your name will be remembered by us!",
    ["STR_ID_SkillEraser[15988][Text301]"] = "Listen, this maybe a little complicated. Take these two Corpse Bags and these two Smell Bags of the two snake races. Use them in the appointed place to entice the elders of the 2 races from their lair and kill them. After the elders are killed!",
    ["STR_ID_SkillEraser[15988][Text302]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text303]"] = "@STR_COMMON[26]",
    ["STR_ID_SkillEraser[15988][Text304]"] = "My scout reported that the two snake races are at war! Thank you for your help! Now we can deliver the final blow!",
    ["STR_ID_SkillEraser[15988][Text305]"] = "Now, carry these 2 Smell Bags and slay 40 Snakemen and 40 Heresy Snakemen. The smell of the other race will be left on the dead body of the Snakemen and Heresy Snakemen. Let`s make their hatred greater!",
    ["STR_ID_SkillEraser[15988][Text306]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text307]"] = "It is great to have you help me! Now, listen carefully to my plan!",
    ["STR_ID_SkillEraser[15988][Text308]"] = "Slay 20 Snakemen and 20 Heresy Snakemen and use these 2 Smell bags to collect their smell.",
    ["STR_ID_SkillEraser[15988][Text309]"] = "The Snakeman and the Heresy Snakeman are two major snake races in Ape City. I have a secret plan to stir up a fight between them! Take these 2 Smell Bags, and go slay 20 Snakemen and 20 Heresy Snakemen to collect their smell.",
    ["STR_ID_SkillEraser[15988][Text310]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text311]"] = "Good job! This plan will not succeed without your help! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text312]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text313]"] = "The Snakeman and the Heresy Snakeman are the two major creatures, here. They usually stir up trouble for us, but I have a plan to pick up a fight between them. Go speak with Harmony Taoist to learn more about the plan!",
    ["STR_ID_SkillEraser[15988][Text314]"] = "Wonderful! With the help of the Cloud Riding, I can bring the criminal back to Ape City and have him punished by law safely! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text315]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text316]"] = "I heard that there is a famous Harmony Taoist here. He must know a shortcut to the Ape City. Go ask him for me! You know, I need to stay here watch this criminal.",
    ["STR_ID_SkillEraser[15988][Text317]"] = "It is all cliff around here. I need to return to the Ape City as soon as possible! What can I do?",
    ["STR_ID_SkillEraser[15988][Text318]"] = "Can you find a shortcut for me? I need to stay here watch this criminal.",
    ["STR_ID_SkillEraser[15988][Text319]"] = "I just captured a wanted criminal! But I am afraid that his friends will come to rescue him. I need to return to Ape City as fast as possible! Can you find a shortcut for me? I need to stay here and watch this ruffian!",
    ["STR_ID_SkillEraser[15988][Text320]"] = "@STR_COMMON[451]",
    ["STR_ID_SkillEraser[15988][Text321]"] = "Thank you very much for slaying my enemies! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text322]"] = "The Snakemen are my enemy! I will wipe them all out! Slay 60 Snakemen for me!",
    ["STR_ID_SkillEraser[15988][Text323]"] = "@STR_COMMON[451]",
    ["STR_ID_SkillEraser[15988][Text324]"] = "I have cast my magic on the Holy Bead and the Heresy Snake Gall! Use the Holy Bead to transform into a Snakeman and challenge the Heresy Leader. Use the Heresy Snake Gall to transform into a Heresy Snakeman to challenge the Snakeman Leader.",
    ["STR_ID_SkillEraser[15988][Text325]"] = "Good. I will cast my magic spell on the Holy Bead and the Heresy Snake Gall! Then you can use it to transform into a Snakeman or a Heresy Snakeman to continue our plan.",
    ["STR_ID_SkillEraser[15988][Text326]"] = "Get a Holy Bead from the Snakeman and a Heresy Snake Gall from the Heresy Snakeman. We need them to pick a fight between the two snake races.",
    ["STR_ID_SkillEraser[15988][Text327]"] = "Listen! We have a plan to pick a fight between the two snake races. Get a Holy Bead from the Snakeman and a Heresy Snake Gall from the Heresy Snakeman. These two items are the key to carry out the plan!",
    ["STR_ID_SkillEraser[15988][Text328]"] = "I have discussed this with Captor Cooke. This will be a big plan!",
    ["STR_ID_SkillEraser[15988][Text329]"] = "Teach Captor Cooke Cloud Riding! We have to help him send the criminals back to Ape City to be punished by the courts!",
    ["STR_ID_SkillEraser[15988][Text330]"] = "Since you have learned the secret of Cloud Riding, you should go teach Captor Cooke how to ride the clouds. We need to help him send the criminals back to Ape City to be punished by the courts!",
    ["STR_ID_SkillEraser[15988][Text331]"] = "You are not a normal person! I knew it at the time when I saw you! See, you mastered the Cloud Riding!",
    ["STR_ID_SkillEraser[15988][Text332]"] = "Go to the cliff closest to Ape City, and chant `Kuh Limb Mah, Kuh Limb Mah` to use the skill! Don`t forget to put away your weapons, first!",
    ["STR_ID_SkillEraser[15988][Text333]"] = "According to the Scroll, you need a pure mind to fly over the cliff. Now, put down your weapon. Go to the cliff closest to Ape City, and chant `Kuh Limb Mah, Kuh Limb Mah` to use the skill!",
    ["STR_ID_SkillEraser[15988][Text334]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text335]"] = "That is it! The Cloud Riding Scroll. It`s written in the Snakemen`s language... Give it to me. I will translate it to you!",
    ["STR_ID_SkillEraser[15988][Text336]"] = "Snakeman has a secret skill of Cloud Riding. As the name suggested, you can raid the cloud flying over the cliffs. Get a Cloud Riding Scroll from the Snakeman and you will know how to fly!",
    ["STR_ID_SkillEraser[15988][Text337]"] = "A shortcut to Ape City? There is one. Fly over the cliff, and there you go! But you`ll need the Cloud Riding Skill to help you!",
    ["STR_ID_SkillEraser[15988][Text338]"] = "I can`t believe it! You made it! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text339]"] = "Slay 50 Snakemen L63 for me! Be careful! They are very aggressive!",
    ["STR_ID_SkillEraser[15988][Text340]"] = "The Snakeman L63 is the most aggressive snake race! I want you to slay 50 Snakemen L63 for me!",
    ["STR_ID_SkillEraser[15988][Text341]"] = "Thank you very much for slaying the Snakeman for me. Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text342]"] = "Slay 60 Snakeman to return peace to Ape City!",
    ["STR_ID_SkillEraser[15988][Text343]"] = "Snakeman is a bane on Ape City! I want you to slay 60 Snakeman and return peace to Ape City!",
    ["STR_ID_SkillEraser[15988][Text344]"] = "Poisonous snakes are dangerous to people!",
    ["STR_ID_SkillEraser[15988][Text345]"] = "Thank you very much for punishing the Snakeman. Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text346]"] = "Go slay the Snakeman and collect 5 Snake Fangs for me! This is will be a warning!",
    ["STR_ID_SkillEraser[15988][Text347]"] = "Many villagers were wounded by the Snakemen. They deserve to be punished! Go slay the Snakemen and collect 5 Snake Fangs for me! This is will be a warning to them!",
    ["STR_ID_SkillEraser[15988][Text348]"] = "Thank you very much for the Snake Gall. Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text349]"] = "The Snake Gall of the Snakeman is a rare medicine, but a necessary ingredient in making the drug for snakebites. Collect 10 Snake Galls for me from the Snakeman!",
    ["STR_ID_SkillEraser[15988][Text350]"] = "The Snake Gall of the Snakeman is a rare medicine, but a necessary ingredient in making the drug for snakebites. Collect 10 Snake Galls for me! I can use them to save lives.",
    ["STR_ID_SkillEraser[15988][Text351]"] = "Well done! The Snakeman Leader must have learnt a lesson this time!",
    ["STR_ID_SkillEraser[15988][Text352]"] = "The Snakeman Leader is an enthusiast in alchemy who likes to eat the bolus produced by the alchemists to strength his power! I have some Catholicon, it some kind of drug for snakebites which is very effective in dealing with the snakes.",
    ["STR_ID_SkillEraser[15988][Text353]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text354]"] = "You want me to punish the Snakeman Leader? that is easy!",
    ["STR_ID_SkillEraser[15988][Text355]"] = "I want to know the limits of man. That is the purpose of my practice, and my goal in life.",
    ["STR_ID_SkillEraser[15988][Text356]"] = "I will do some research on these Rage Stones. Thank you very much for your help!",
    ["STR_ID_SkillEraser[15988][Text357]"] = "Collect 3 Rage Stones for me from the Thunder Ape L58.",
    ["STR_ID_SkillEraser[15988][Text358]"] = "The Rage Stones of the Thunder Apes L58 can really boost their strength! I hope you can collect 3 Rage Stones for me.",
    ["STR_ID_SkillEraser[15988][Text359]"] = "@STR_COMMON[439]",
    ["STR_ID_SkillEraser[15988][Text360]"] = "Please collect 3 Thunder Stones for me from the Thunder Apes. I need to do a research on them!",
    ["STR_ID_SkillEraser[15988][Text361]"] = "Thunder Apes usually carry the Thunder Stones. I guess these strange stones give them special power! Will you collect 3 Thunder Stones for me, for further research?",
    ["STR_ID_SkillEraser[15988][Text362]"] = "Thank you very much for your medicine! We can use them to enter the lair of the apes and find out the way to deal with them.",
    ["STR_ID_SkillEraser[15988][Text363]"] = "The goal of the Taoist practice is to achieve harmony in both the mental and physical planes.",
    ["STR_ID_SkillEraser[15988][Text364]"] = "My brother, the Tempest Taoist, and I decided to enter the lair of the Giant Apes, but we can`t afford the necessary medicine. Please, buy 2 Amrita and 2 Pearl Ointments for my brother and I. I will give you all I have in return.",
    ["STR_ID_SkillEraser[15988][Text365]"] = "Thank you very much for wiping out the Thunder Apes L58 for me! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text366]"] = "Slay 50 Thunder Apes L58 for me! Be quick!",
    ["STR_ID_SkillEraser[15988][Text367]"] = "Why can`t they stop bothering me! Go slay 50 Thunder Apes L58 for me! I need a quiet place for my practice!",
    ["STR_ID_SkillEraser[15988][Text368]"] = "@STR_COMMON[434]",
    ["STR_ID_SkillEraser[15988][Text369]"] = "Thank you very much for wiping out the Thunder Apes for me! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text370]"] = "I hope you can slay 60 Thunder Apes for me. Maybe then I can continue with my studies and practice.",
    ["STR_ID_SkillEraser[15988][Text371]"] = "The Thunder Apes are such a nuisance to me! They keep on interrupting my practice. Take this Soulfire Token and slay 60 Thunder Apes for me!",
    ["STR_ID_SkillEraser[15988][Text372]"] = "@STR_COMMON[26]",
    ["STR_ID_SkillEraser[15988][Text373]"] = "I will become a great taoist in the future!",
    ["STR_ID_SkillEraser[15988][Text374]"] = "Please find the Moon Maiden for me!",
    ["STR_ID_SkillEraser[15988][Text375]"] = "Everytime I entered the habitation of the Snakemen, I was bullied by the Snakeman Leader. I heard that the Moon Maiden is an expert in dealing with the Snakemen and making drugs for snakebite. Will you find her and ask her to help me?",
    ["STR_ID_SkillEraser[15988][Text376]"] = "@STR_COMMON[439]",
    ["STR_ID_SkillEraser[15988][Text377]"] = "Capture 5 Thunder Apes and 5 Thunder Apes L58 for me.",
    ["STR_ID_SkillEraser[15988][Text378]"] = "My master gave me a Ape Gourd. He told me that I can use it to capture some Apes. Use it to Capture 5 Thunder Apes and 5 Thunder Apes L58 for me.",
    ["STR_ID_SkillEraser[15988][Text379]"] = "@STR_COMMON[440]",
    ["STR_ID_SkillEraser[15988][Text380]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text381]"] = "Thank you very much for retrieving my Blaze Pill! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text382]"] = "I need your help. Please bring the Blaze Pill back to me!",
    ["STR_ID_SkillEraser[15988][Text383]"] = "My master gave me a Blaze Pill. But the Thunder Ape grabbed it away. If my master knows that I lost the pill, he will be mad at me. Please find the pill back for me.",
    ["STR_ID_SkillEraser[15988][Text384]"] = "The purpose of studying poison is to save people`s lives!",
    ["STR_ID_SkillEraser[15988][Text385]"] = "Thank you very much for your help! The ape problem will be solved! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text386]"] = "I have a plan to deal with the Apes. They`re very curious creatures. I am sure they will eat the Enervation Pill when they find it. I will give you a bottle of Enervation Pill. Spread the pills in the required position. After the Apes eat the pills,",
    ["STR_ID_SkillEraser[15988][Text387]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text388]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text389]"] = "@STR_COMMON[439]",
    ["STR_ID_SkillEraser[15988][Text390]"] = "Now, I want to put the Enervation Pill in the really tough battle. There is a Raging Ape in the wild. Feed the Enervation Pill to him and kill it!",
    ["STR_ID_SkillEraser[15988][Text391]"] = "There is a Raging Ape in the wild. Feed the Enervation Pill to him and kill it!",
    ["STR_ID_SkillEraser[15988][Text392]"] = "Thank you very much for testing the Enervation Pill for me! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text393]"] = "Go and find a Thunder Ape L58 and feed it the Enervation Pill and kill it!",
    ["STR_ID_SkillEraser[15988][Text394]"] = "This time, I want to test the Enervation Pill on a real ape. Go find a Thunder Ape L58 and feed it the Enervation Pill and kill it! Don`t forget to tell me its response.",
    ["STR_ID_SkillEraser[15988][Text395]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text396]"] = "Thank you very much for helping me test the poison! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text397]"] = "Okay! This is the medicine I made! I call it Enervation Pill. Take Transmute Pill to transform into an Ape and then take the Enervation Pill to see what will happen on you!",
    ["STR_ID_SkillEraser[15988][Text398]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text399]"] = "Yes, that is the Transmute Pill. Let`s go to the next step.",
    ["STR_ID_SkillEraser[15988][Text400]"] = "Go get the Transmute Pill from my old friend, the Apothecary!",
    ["STR_ID_SkillEraser[15988][Text401]"] = "I have a good news to share with you! I made a new medicine! It can weaken the apes, but it does no harm to humans. So I can`t use my body to test its potency. Can you get a Transmute Pill from the Apothecary to transform into an Ape",
    ["STR_ID_SkillEraser[15988][Text402]"] = "@STR_COMMON[456]",
    ["STR_ID_SkillEraser[15988][Text403]"] = "Here is the final test! Jump off the cliff.  If you are a man of dignity, righteousness and courage, you will be lifted up by the clouds! Dare you try this?",
    ["STR_ID_SkillEraser[15988][Text404]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text405]"] = "@STR_COMMON[456]",
    ["STR_ID_SkillEraser[15988][Text406]"] = "Kill the Thunder Ape King to prove your courage to me!",
    ["STR_ID_SkillEraser[15988][Text407]"] = "You passed one of my Courage Test, but it is only a beginning. Now, kill the Thunder Ape King!",
    ["STR_ID_SkillEraser[15988][Text408]"] = "@STR_COMMON[457]",
    ["STR_ID_SkillEraser[15988][Text409]"] = "@STR_COMMON[456]",
    ["STR_ID_SkillEraser[15988][Text410]"] = "@STR_COMMON[457]",
    ["STR_ID_SkillEraser[15988][Text411]"] = "Dare you take this Toxicant?",
    ["STR_ID_SkillEraser[15988][Text412]"] = "People told me that you are brave. But I don`t believe it! You need to prove it to me! I made a new Toxicant! Dare you take it to test its power like me?",
    ["STR_ID_SkillEraser[15988][Text413]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text414]"] = "Thank you very much for the Thunder Ginseng you collected! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text415]"] = "Use the Sickle to collect 10 Thunder Ginsengs for me!",
    ["STR_ID_SkillEraser[15988][Text416]"] = "I need 10 Thunder Ginsengs to make an antidote to a rare poison. Take this Sickle and collect 10 Thunder Ginsengs for me!",
    ["STR_ID_SkillEraser[15988][Text417]"] = "@STR_COMMON[26]",
    ["STR_ID_SkillEraser[15988][Text418]"] = "Thank you. I can use this Bezoar to purge the remaining poison from my body!",
    ["STR_ID_SkillEraser[15988][Text419]"] = "I have been doctored in Ape City for decades. Saving people is my job!",
    ["STR_ID_SkillEraser[15988][Text420]"] = "Poison Master asked you to get a Transmute Pill from me? My friend must have an interesting plan! Ok, this is the Transmute Pill you need!",
    ["STR_ID_SkillEraser[15988][Text421]"] = "@STR_COMMON[416]",
    ["STR_ID_SkillEraser[15988][Text422]"] = "@STR_COMMON[416]",
    ["STR_ID_SkillEraser[15988][Text423]"] = "Please send the Quality Bezoar to my friend Poison Master.",
    ["STR_ID_SkillEraser[15988][Text424]"] = "My friend Poison Master dedicated his life to the research of poison. He even use himself to try the poison and find out the way of detoxification. I am worrying about his body! After so many years of trial, many toxin must have remained in his body!",
    ["STR_ID_SkillEraser[15988][Text425]"] = "Thank you very much for testing the Weary Pill! It seems that it is safe to mankind! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text426]"] = "After years of study! I developed a Weary Pill that can deal with the apes in Ape City! But I need someone to test it whether it`s harmful to human beings. Will you try this Weary Pill? Don`t worry, I am a doctor, I can save you if anything bad happens.",
    ["STR_ID_SkillEraser[15988][Text427]"] = "@STR_COMMON[416]",
    ["STR_ID_SkillEraser[15988][Text428]"] = "These are what I have been looking for! Thank you!",
    ["STR_ID_SkillEraser[15988][Text429]"] = "The wounded soldiers are waiting for medicine. Collect 1 Ape Claw, 1 Ape Bone, and 1 Ape Skin for me to make a medicine to treat them!",
    ["STR_ID_SkillEraser[15988][Text430]"] = "Many soldiers were wounded by the monkeys. Collect 1 Ape Claw, 1 Ape Bone, and 1 Ape Skin for me! I can will make a medicine to treat the wounded soldiers.",
    ["STR_ID_SkillEraser[15988][Text431]"] = "I am the only carpenter in Ape City.",
    ["STR_ID_SkillEraser[15988][Text432]"] = "Yes! That is the flower I have been looking for! It can help us to consolidate the bridges! Here are your rewards.",
    ["STR_ID_SkillEraser[15988][Text433]"] = "My master told me that the juice of the Cliff Flower can be painted on the wood to prevent it from decaying and make it stronger.",
    ["STR_ID_SkillEraser[15988][Text434]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text435]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text436]"] = "The wood is arriving? Good! I will have enough materials to fix the wooden bridge! Thank you very much!",
    ["STR_ID_SkillEraser[15988][Text437]"] = "@STR_COMMON[444]",
    ["STR_ID_SkillEraser[15988][Text438]"] = "Please go visit Jack Daniel.",
    ["STR_ID_SkillEraser[15988][Text439]"] = "The wooden bridge outside Ape City need to be fixed, but I don`t have enough wood. Speak with Jack Daniel to get some wood for me!",
    ["STR_ID_SkillEraser[15988][Text440]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text441]"] = "Thank you very much! This bottle of Bamboo Liquid can be a nice, little refreshment for me!",
    ["STR_ID_SkillEraser[15988][Text442]"] = "It`s difficult to manage a city. There are too many things you need to think about!",
    ["STR_ID_SkillEraser[15988][Text443]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text444]"] = "Please go visit Carpenter Jack, and bring him the Bamboo Liquid.",
    ["STR_ID_SkillEraser[15988][Text445]"] = "Carpenter Jack helped us a lot by fixing the wooden bridge outside the city. I want you to visit him and bring him this bottle of Bamboo Liquid, to express our gratitude.",
    ["STR_ID_SkillEraser[15988][Text446]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text447]"] = "You brought peace back to the city! Thank you very much for your help. Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text448]"] = "@STR_COMMON[478]",
    ["STR_ID_SkillEraser[15988][Text449]"] = "@STR_COMMON[478]",
    ["STR_ID_SkillEraser[15988][Text450]"] = "You brought peace to the city! Thank you very much for your help. Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text451]"] = "Go get a Vulture Feather and burn it in the city. The other Vultures will never come near Ape City, after that!",
    ["STR_ID_SkillEraser[15988][Text452]"] = "We are quite annoyed by the Vultures outside Ape City, but I have an effective way to drive them far away from the city! If we get a Vulture Feather and burn it in the city, the other Vultures won`t dare come back!",
    ["STR_ID_SkillEraser[15988][Text453]"] = "The price of gold will soar! Believe me!",
    ["STR_ID_SkillEraser[15988][Text454]"] = "These are my Jewelry Boxes. Thank you very much for helping me! Here are some rewards for you!",
    ["STR_ID_SkillEraser[15988][Text455]"] = "Please! Please retrieve 20 Jewelry Boxes for me from the Macaques!",
    ["STR_ID_SkillEraser[15988][Text456]"] = "The Macaques broke in the house and ran away with 20 of my Jewelry Boxes! They`re all I have! Will you bring them back for me?",
    ["STR_ID_SkillEraser[15988][Text457]"] = "@STR_COMMON[440]",
    ["STR_ID_SkillEraser[15988][Text458]"] = "What would be the proof of a hero? A true hero never falters, even when the enemy is at the gates!",
    ["STR_ID_SkillEraser[15988][Text459]"] = "Good job! Here are your rewards! Thank you very much for your help!",
    ["STR_ID_SkillEraser[15988][Text460]"] = "Slay 1 Monkey King to return peace to Ape City.",
    ["STR_ID_SkillEraser[15988][Text461]"] = "This time, our target is the Monkey King. Slay the Monkey King and bring back its tail. It will help inspire the people in Ape City,",
    ["STR_ID_SkillEraser[15988][Text462]"] = "@STR_COMMON[26]",
    ["STR_ID_SkillEraser[15988][Text463]"] = "You gave the Macaques a heavy blow. I think they will think twice before coming, again. Thank you very much for your help. Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text464]"] = "Slay 30 MacaquesL48 to return peace to Ape City.",
    ["STR_ID_SkillEraser[15988][Text465]"] = "According to my observations, the Macaques L48 are the upper level forces of the apes. I need you to slay 30 Macaques L48 for me, to weaken them.",
    ["STR_ID_SkillEraser[15988][Text466]"] = "I am quite impressed by your performance! Here are your rewards!",
    ["STR_ID_SkillEraser[15988][Text467]"] = "Slay 50 Macaques to return peace to Ape City.",
    ["STR_ID_SkillEraser[15988][Text468]"] = "The naughty Macaques has been making trouble in the city for too long! We are tired of the constant noise, and don`t get",
    ["STR_ID_SkillEraser[15988][Text469]"] = "@STR_COMMON[439]",
    ["STR_ID_SkillEraser[15988][Text470]"] = "Please go appease the souls of my fallen soldiers on the battlefield.",
    ["STR_ID_SkillEraser[15988][Text471]"] = "I lost 5 of my best men in a decisive battle. They appeared to me one night, in a vision. Their souls are still wandering",
    ["STR_ID_SkillEraser[15988][Text472]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text473]"] = "Nice to see you, hero! It is great that you came to Ape City. We could use the help. You need to keep your eyes open, while you`re here.",
    ["STR_ID_SkillEraser[15988][Text474]"] = "@STR_COMMON[439]",
    ["STR_ID_SkillEraser[15988][Text475]"] = "For the safety of the town, you must wipe out 50 Vultures gathered outside of Ape City!",
    ["STR_ID_SkillEraser[15988][Text476]"] = "Many Vultures appeared at the gates of Ape City. For the safety of the town, I hope you can help us slay 50 Vultures.",
    ["STR_ID_SkillEraser[15988][Text477]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text478]"] = "We have various kinds of stores in the market. But if you are interested in some rare items with special effect, I will be the",
    ["STR_ID_SkillEraser[15988][Text479]"] = "How do you like it? I have lots of those items. When you need them, don`t hesitate to let me know!",
    ["STR_ID_SkillEraser[15988][Text480]"] = "Just right click this EXP Potion to activate a 10 minute double EXP bonus. Talk to me again when you`re done.",
    ["STR_ID_SkillEraser[15988][Text481]"] = "You can buy some unusual items in the Shopping Mall. To enter it, talk to the Great Merchant",
    ["STR_ID_SkillEraser[15988][Text482]"] = "I guess you don`t know what that is yet, right?",
    ["STR_ID_SkillEraser[15988][Text483]"] = "Please take this EXP Potion as a present, you will obtain a 10 mins double EXP bonus when using it.",
    ["STR_ID_SkillEraser[15988][Text484]"] = "@STR_COMMON[14]",
    ["STR_ID_SkillEraser[15988][Text485]"] = "The rules of Super Guild War it's same with the Guild War. It`s a Guild Tournament that takes place every Tuesday at 00:00 AM and will finish Tuesday 20:00.",
    ["STR_ID_SkillEraser[15988][Text486]"] = "@STR_COMMON[661]",
    ["STR_ID_SkillEraser[15988][Text487]"] = "@STR_COMMON[662]",
    ["STR_ID_SkillEraser[15988][Text488]"] = "@STR_COMMON[470]",
    ["STR_ID_SkillEraser[15988][Text489]"] = "@STR_COMMON[663]",
    ["STR_ID_SkillEraser[15988][Text490]"] = "@STR_COMMON[661]",
    ["STR_ID_SkillEraser[15988][Text491]"] = "A~good~set~of~equipment~can~help~you~a~lot~in~future~battles.~Is~there~something~I~can~do~for~you?",
    ["STR_ID_SkillEraser[15988][Text492]"] = "You can obtain Composition Points from minor items and make your main items reach the next bonus level on the Forging interface.",
    ["STR_ID_SkillEraser[15988][Text493]"] = "There are two ways to refine items. \n1 .Right click the refined items and click the equipment with the same type to refine.",
    ["STR_ID_SkillEraser[15988][Text494]"] = "You may promote the bonus level of items on the Forging interface, namely compose +n items. +n items have +n stats which",
    ["STR_ID_SkillEraser[15988][Text495]"] = "The enchanted weapon can increase up to 255 HP. The higher quality gem will enchant higher HP. The enchanted effects vary with different gems.",
    ["STR_ID_SkillEraser[15988][Text496]"] = "You can promote the bonus level of weapon on the Forging interface. Put the weapon and the enchanted materials into the designated places, then begin to enchant.",
    ["STR_ID_SkillEraser[15988][Text497]"] = "Sure. You can re-enchant your weapon on the Forging interface. If the new attribute is higher, it will replace the old one, otherwise, it won`t replace.",
    ["STR_ID_SkillEraser[15988][Text498]"] = "They can be Dragon, Phoenix, Tortoise, Rainbow, Moon, Violet, Fury, or Kylin. The enchanted effects vary with the gem quality.",
    ["STR_ID_SkillEraser[15988][Text499]"] = "Just paying 10.000 CPs, you`re able to activate the Wuxing Oven and attach 1 blessed attribute on specific equipment. It`s different from that attributes upgraded with Tortoise Gems.",
    ["STR_ID_SkillEraser[15988][Text500]"] = "Are you sure you want to pay 1.000 CPs to add 1 blessed attribute to the LeftWeapon?",
